# Shared helpers for the rusterp distribution CLI (Phase 3).
# Safe to source from tests. No network side effects.

# Default git ref for `rusterp install core` when --branch is omitted.
RUSTERP_DEFAULT_CORE_BRANCH="${RUSTERP_DEFAULT_CORE_BRANCH:-dist}"

# Upstream clone URL (override for forks / airgap mirrors).
RUSTERP_REPO_URL="${RUSTERP_REPO_URL:-https://github.com/ndx-au/RustERP.git}"

rusterp_default_home() {
  if [ -n "${RUSTERP_HOME:-}" ]; then
    printf '%s\n' "$RUSTERP_HOME"
    return 0
  fi
  if [ "$(id -u)" -eq 0 ]; then
    printf '%s\n' "/opt/rusterp"
  else
    printf '%s\n' "${HOME}/.local/share/rusterp"
  fi
}

rusterp_default_bin_dir() {
  if [ -n "${RUSTERP_BIN_DIR:-}" ]; then
    printf '%s\n' "$RUSTERP_BIN_DIR"
    return 0
  fi
  if [ "$(id -u)" -eq 0 ]; then
    printf '%s\n' "/usr/local/bin"
  else
    printf '%s\n' "${HOME}/.local/bin"
  fi
}

rusterp_die() {
  printf 'rusterp: error: %s\n' "$*" >&2
  exit 1
}

rusterp_info() {
  printf 'rusterp: %s\n' "$*" >&2
}

# Print a clear missing-tool message and exit 1.
rusterp_require_cmd() {
  local cmd="$1"
  local hint="$2"
  if ! command -v "$cmd" >/dev/null 2>&1; then
    printf 'rusterp: error: required command not found: %s\n' "$cmd" >&2
    printf 'rusterp: %s\n' "$hint" >&2
    return 1
  fi
  return 0
}

rusterp_require_build_tools() {
  rusterp_require_cmd git \
    "Install git, then re-run. Example: apt install git / brew install git" || return 1
  rusterp_require_cmd cargo \
    "Install a stable Rust toolchain (rustup), then re-run: https://rustup.rs" || return 1
  # protoc is required to build rusterp-proto / rusterp-server from source.
  if ! command -v protoc >/dev/null 2>&1; then
    printf 'rusterp: error: required command not found: protoc\n' >&2
    printf 'rusterp: Install the Protocol Buffers compiler, then re-run.\n' >&2
    printf 'rusterp: Example: apt install protobuf-compiler / brew install protobuf\n' >&2
    return 1
  fi
  return 0
}

# Parse `install core` argv after the subcommand words.
# Sets globals: RUSTERP_PARSE_BRANCH, RUSTERP_PARSE_ERR
# Usage: rusterp_parse_install_core_args "$@"
rusterp_parse_install_core_args() {
  RUSTERP_PARSE_BRANCH="$RUSTERP_DEFAULT_CORE_BRANCH"
  RUSTERP_PARSE_ERR=""
  while [ "$#" -gt 0 ]; do
    case "$1" in
      --branch)
        if [ "$#" -lt 2 ] || [ -z "${2:-}" ]; then
          RUSTERP_PARSE_ERR="missing value for --branch"
          return 1
        fi
        RUSTERP_PARSE_BRANCH="$2"
        shift 2
        ;;
      --branch=*)
        RUSTERP_PARSE_BRANCH="${1#--branch=}"
        if [ -z "$RUSTERP_PARSE_BRANCH" ]; then
          RUSTERP_PARSE_ERR="missing value for --branch"
          return 1
        fi
        shift
        ;;
      -h | --help)
        RUSTERP_PARSE_ERR="help"
        return 2
        ;;
      *)
        RUSTERP_PARSE_ERR="unknown argument: $1"
        return 1
        ;;
    esac
  done
  return 0
}

rusterp_core_paths() {
  # Sets: RUSTERP_HOME_RESOLVED SRC_DIR BIN_DIR STATE_DIR SERVER_BIN RUN_SCRIPT
  RUSTERP_HOME_RESOLVED="$(rusterp_default_home)"
  SRC_DIR="${RUSTERP_HOME_RESOLVED}/src"
  BIN_DIR="${RUSTERP_HOME_RESOLVED}/bin"
  STATE_DIR="${RUSTERP_HOME_RESOLVED}/state"
  SERVER_BIN="${BIN_DIR}/rusterp-server"
  RUN_SCRIPT="${BIN_DIR}/run-core"
}

rusterp_write_run_script() {
  local dest="$1"
  local server_bin="$2"
  local listen_default="${RUSTERP_LISTEN:-127.0.0.1:50051}"
  cat >"$dest" <<EOF
#!/usr/bin/env bash
# Generated by rusterp install core — runs in-memory gRPC core (auth not enforced).
set -euo pipefail
export RUSTERP_LISTEN="\${RUSTERP_LISTEN:-${listen_default}}"
exec "${server_bin}" --listen "\${RUSTERP_LISTEN}"
EOF
  chmod +x "$dest"
}

rusterp_write_core_env_example() {
  local dest="$1"
  cat >"$dest" <<'EOF'
# RustERP core env (Terraform / systemd EnvironmentFile friendly)
# Copy or point unit at this file. Auth is not enforced. Persistence is in-memory.
RUSTERP_LISTEN=127.0.0.1:50051
# RUSTERP_HOME is the install prefix (source tree + binaries), not a durable DB path yet.
EOF
}
